#include <iostream>
#include <iomanip>
#include <string>
#include <vector>
#include <cstdint>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<string> s(N);
    for (string& str : s) cin >> str;

    const int M = static_cast<int>(s[0].size());
    const int limit = 1 << M;

    vector<uint64_t> bm(limit, 0);
    vector<double> dp(limit, 0.0);

    for (int i = 0; i < N; ++i) {
        for (int j = i + 1; j < N; ++j) {
            int mask = 0;
            for (int k = 0; k < M; ++k) {
                if (s[i][k] == s[j][k]) {
                    mask |= 1 << k;
                }
            }
            bm[mask] |= (uint64_t{1} << i) | (uint64_t{1} << j);
        }
    }

    for (int bit = 0; bit < M; ++bit) {
        for (int mask = 0; mask < limit; ++mask) {
            if ((mask & (1 << bit)) == 0) {
                bm[mask] |= bm[mask | (1 << bit)];
            }
        }
    }

    for (int mask = limit - 2; mask >= 0; --mask) {
        if (bm[mask] == 0) continue;

        const int remaining = M - __builtin_popcount(static_cast<unsigned>(mask));
        const double total = static_cast<double>(__builtin_popcountll(bm[mask]));

        for (int bit = 0; bit < M; ++bit) {
            if ((mask & (1 << bit)) != 0) continue;

            const int next = mask | (1 << bit);
            const double separated = static_cast<double>(
                __builtin_popcountll(bm[mask] & ~bm[next])
            );
            const double probability = separated / total;

            dp[mask] +=
                ((dp[next] + 1.0) * (1.0 - probability) + probability)
                / remaining;
        }
    }

    cout << fixed << setprecision(12) << dp[0] << '\n';
    return 0;
}

#include <iostream>
#include <iomanip>
#include <string>
#include <vector>
#include <cstdint>

using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<string> s(N);
    for (string& str : s) cin >> str;

    const int M = static_cast<int>(s[0].size());
    const int limit = 1 << M;

    vector<uint64_t> ambiguous(limit, 0);
    vector<double> dp(limit, 0.0);
    vector<int> bitCount(limit, 0);

    for (int i = 0; i < N; ++i) {
        for (int j = i + 1; j < N; ++j) {
            int mask = 0;
            for (int k = 0; k < M; ++k) {
                if (s[i][k] == s[j][k]) {
                    mask |= 1 << k;
                }
            }
            ambiguous[mask] |= (uint64_t{1} << i);
            ambiguous[mask] |= (uint64_t{1} << j);
        }
    }

    for (int bit = 0; bit < M; ++bit) {
        for (int mask = 0; mask < limit; ++mask) {
            if ((mask & (1 << bit)) == 0) {
                ambiguous[mask] |= ambiguous[mask | (1 << bit)];
            }
        }
    }

    for (int mask = 1; mask < limit; ++mask) {
        bitCount[mask] = bitCount[mask >> 1] + (mask & 1);
    }

    for (int mask = limit - 2; mask >= 0; --mask) {
        const uint64_t current = ambiguous[mask];
        if (current == 0) continue;

        const int total = __builtin_popcountll(current);
        const double choiceProbability =
            1.0 / static_cast<double>(M - bitCount[mask]);

        for (int bit = 0; bit < M; ++bit) {
            if ((mask & (1 << bit)) != 0) continue;

            const int nextMask = mask | (1 << bit);
            const int unresolved =
                __builtin_popcountll(ambiguous[nextMask]);
            const double remainProbability =
                static_cast<double>(unresolved) / total;

            dp[mask] +=
                (1.0 + remainProbability * dp[nextMask]) *
                choiceProbability;
        }
    }

    cout << fixed << setprecision(12) << dp[0] << '\n';
    return 0;
}

#include <iostream>
#include <cstdio>
#include <string>
using namespace std;

string s[51];
double dp[1 << 20];
long long bm[1 << 20];
int bits[1 << 20];
int N, M;

void prep() {
    int lim = 1 << M;

    for (int i = 0; i < lim; ++i)
        bm[i] = 0;

    for (int i = 0; i < N; ++i) {
        for (int j = i + 1; j < N; ++j) {
            int mask = 0;
            for (int k = 0; k < M; ++k) {
                if (s[i][k] == s[j][k])
                    mask |= 1 << k;
            }
            bm[mask] |= (1LL << i) | (1LL << j);
        }
    }

    for (int mask = lim - 1; mask >= 0; --mask) {
        for (int bit = 0; bit < M; ++bit) {
            if (mask & (1 << bit))
                bm[mask ^ (1 << bit)] |= bm[mask];
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N;
    for (int i = 0; i < N; ++i)
        cin >> s[i];

    M = static_cast<int>(s[0].size());
    int lim = 1 << M;

    prep();

    bits[0] = 0;
    for (int i = 1; i < lim; ++i)
        bits[i] = bits[i >> 1] + (i & 1);

    dp[lim - 1] = 0.0;

    for (int mask = lim - 2; mask >= 0; --mask) {
        if (bm[mask] == 0) {
            dp[mask] = 0.0;
            continue;
        }

        int total = __builtin_popcountll(bm[mask]);
        double choiceProbability = 1.0 / (M - bits[mask]);
        double expected = 0.0;

        for (int bit = 0; bit < M; ++bit) {
            if (!(mask & (1 << bit))) {
                int next = mask | (1 << bit);
                int resolved = __builtin_popcountll(
                    bm[mask] & ~bm[next]
                );
                double probabilityResolved =
                    static_cast<double>(resolved) / total;

                expected += (
                    (dp[next] + 1.0) * (1.0 - probabilityResolved) +
                    probabilityResolved
                ) * choiceProbability;
            }
        }

        dp[mask] = expected;
    }

    printf("%.12f\n", dp[0]);
    return 0;
}

